+import org.slf4j.LoggerFactory;
+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians, with incremental loading as the visitor scrolls. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        Grid<Vet> grid = new Grid<>();
+        grid.setSizeFull();
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                ? "none" : String.join(", ", vet.specialties())).setHeader("Specialties");
+        grid.setItems(query -> fetchPage(query.getOffset(), query.getLimit()),
+                query -> count());
+
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetchPage(int offset, int limit) {
+        try {
+            return repository.findPage(offset, limit);
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        LoggerFactory.getLogger(VetsView.class).error("Unable to load veterinarians", exception);
+        // Lazy callbacks run after navigation. Flow's RPC error helper requires
+        // the exact handled type (Exception for ApplicationErrorView).
+        ErrorHandlerUtil.handleErrorByRedirectingToErrorView(
+                new Exception("Unable to load veterinarians."));
+    }
+}
