+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void navigationOpensDirectoryWithoutAuthentication() {
+        navigate(WelcomeView.class);
+        SideNav menu = assertDoesNotThrow(() -> find(SideNav.class).single(), "Expected main menu");
+        test(menu).clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        var grid = test(directoryGrid());
+        assertEquals(6, grid.size());
+        assertEquals("First Name", grid.getHeaderCell(0));
+        assertEquals("Last Name", grid.getHeaderCell(1));
+        assertEquals("Specialties", grid.getHeaderCell(2));
+        assertEquals("James", grid.getCellText(0, 0));
+        assertEquals("Carter", grid.getCellText(0, 1));
+        assertEquals("none", grid.getCellText(0, 2));
+        assertEquals("Helen", grid.getCellText(3, 0));
+        assertEquals("radiology", grid.getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must not modify the directory");
