+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreAlphabeticalAndCommaSeparated() {
+        navigate(VetsView.class);
+        var grid = test(directoryGrid());
+
+        // Seed data links Linda to surgery before dentistry.
+        assertEquals("Linda", grid.getCellText(1, 0));
+        assertEquals("Douglas", grid.getCellText(1, 1));
+        assertEquals("dentistry, surgery", grid.getCellText(1, 2));
