+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void dataProviderFetchesBoundedNonOverlappingPagesThroughTheEnd() {
+        for (int index = 0; index < 125; index++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Page", "Vet" + index).execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = directoryGrid();
+        assertFalse(grid.getDataProvider().isInMemory(), "The directory must use backend loading");
+        assertFalse(grid.isAllRowsVisible(), "The grid must retain its scrolling viewport");
+        assertEquals(131, grid.getDataProvider().size(new Query<>()));
+
+        var ids = new HashSet<Integer>();
+        for (int offset = 0; offset < 131; offset += 20) {
+            List<Vet> page = grid.getDataProvider()
+                    .fetch(new Query<>(offset, 20, List.of(), null, null)).toList();
+            assertEquals(Math.min(20, 131 - offset), page.size());
+            for (Vet vet : page) {
+                assertTrue(ids.add(vet.id()), "Pages must not repeat veterinarians");
+            }
+        }
+        assertEquals(131, ids.size());
+        assertTrue(grid.getDataProvider()
+                .fetch(new Query<>(131, 20, List.of(), null, null)).findAny().isEmpty());
